-- GENERATED by `wfj generate` from data/quest/quest-0091.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [91208] = { "受け入れる", "DeathknellでFrightened Paladinを見つけてください。", "蘇った同胞のパラディンが皆、我々の新たな現実にすぐ馴染めるわけではありません。自分たちが今や、ある意味で、生涯をかけて戦ってきたものそのものになったという事実を受け入れられずに苦しむ者もいます。\n\nそうした者たちは、多くの場合、優しい態度と、共感して耳を傾けてくれる相手を必要としているだけです。残念ながら、すぐに暴力に走る者も多いのです。この礼拝堂のすぐ西の丘へ逃げ込んだ、怯えたパラディンを見つけてください。友情の手を差し伸べてください。できるなら、その者を光のもとへ連れ戻してあげてください。", nil, nil, 0x369056a8, 0x4e575d59, 0xf3aba797, nil, nil, "...mm" },
  [91209] = { "訓練の続き", "Deathknellから東へ道をたどり、Brillの町を見つけてください。訓練を続けるため、Shari Stilwellに報告してください。", "Lordaeronはかつての姿ではないかもしれませんが、我らの故郷は今もあらゆる脅威から守られる必要があります。あなたが外の世界へ出て向き合う時が来ました。次の行き先はTirisfal Glades中央のBrillの町です。そこでShari Stilwellに会ってください。彼女があなたの訓練の続きを見てくれるでしょう。\n\n出発する前に最後の助言を――Forsakenの地を旅するパラディンとして、十分に気をつけてください。Dark Ladyに仕える者の中には、我々と、我々が光に近いことを疑う者が大勢いるのです。", nil, nil, 0x4085cde1, 0x85d93d6b, 0xaa599bfa, nil, nil, "...mm" },
  [91282] = { "第二の故郷", "Bandarion Keepの砦を見つけ、そこにいるBreton Samuelsに報告してください。", "蘇った兄弟姉妹たちがあなたのように力をつけていく姿を見るのは心強いことです。しかし、真に持てる力を発揮できるのは、共同体と信仰の共有があってこそです。そのために、我々はここTirisfalで新たなパラディンの騎士団を結成し始めました。\n\nもっと知りたいなら、Northface Rockにある我々の修道院を訪ねるとよいでしょう。Bandarion Keepという名です。Solliden Farmsteadのすぐ北西の断崖の上にあるので、見逃すことはないはずです。", nil, nil, 0x323b0ccf, 0x66582164, 0xe91ac1c9, nil, nil, "...mm" },
  [91285] = { "門に迫るMurloc", "Vile Fin Attackerを$N1体とVile Fin Seerを$N2体倒し、終わったらBreton Samuelsに報告してください。", "普段なら新入りにもう少しもてなしをするんだが、今はちょっとmurlocの問題を抱えていてね。\n\nmurlocの一族がかつてこの砦を産卵場にしていたんだ。俺たちが移ってきて追い出して以来ずっと厄介だったが、最近は手に負えなくなってきている。君は場数を踏んできたように見える。この害獣どもを追い払うのを手伝ってくれないか？ 東へ続く道沿いの断崖や、西の湖の周りの野営地に潜んでいるはずだ。", nil, nil, 0x7785ffc2, 0x7b21c67e, 0x12268215, nil, nil, "...mm" },
  [91294] = { "敷地を巡る", "Bandarion Keepの住人たちと話してください。", "murlocの襲撃という差し迫った脅威は収まったから、我々の拠点を見て回るといい。まだ大したものじゃないが、ここが我が家だ。\n\n見て回ったら、我々のリーダーのDanitha Morrを訪ねてくれ。彼女が落ち着けるよう手を貸してくれるだろう。\n\n会えて本当に嬉しかったよ、{name}。光が君を導かんことを。", nil, nil, 0x2887ca72, 0x410e846c, 0x44585301, nil, nil, "...mm" },
  [91316] = { "修理", "Tirisfal GladesのShadowvaleでSturdy Lumberを12個集めてください。", "Undercityからこれほど離れていると補給が難しく、この砦を修復するのに必要な建材がひどく不足している。その件で君の手を借りたい。\n\n廃墟となったShadowvaleの村は、ここから南西のWhispering Forestにある。建物の一つに、あらゆる物をしまっておく古い地下貯蔵庫がある。そこなら使える資材があるだろう。集められるだけ集めて戻ってきてくれ。", nil, nil, 0x2cfcd9f0, 0xb8282c24, 0x1518690b, nil, nil, "...mm" },
  [91317] = { "Tarnished", "Tirisfal GladesでTarnished Drudgeを8体、Tarnished Zealotを6体倒し、Commander Rudolph Gelhardtの首を手に入れてください。", "君もすでに目にしたかもしれないが、蘇ったパラディンの皆が新たな存在にうまく馴染めたわけではない。生前の偏見を持ち越し、同胞のForsakenに暴力を振るい続ける者もいる。\n\n現状、我々は同胞から信用されていない。彼らは、生者が光の名のもとに加えた迫害をよく覚えているからだ。そしてこうした襲撃はそれを悪化させるだけだ。こうした堕ちた者たちの一団が、南西のShadowvaleに住み着いている。奴らを始末し、その首領の首を持ってきてくれ。", nil, nil, 0x56e9442f, 0x783dab34, 0x72df7fd8, nil, nil, "...mm" },
  [91723] = { "繊細な計器", "Jasperlode MineでKobold Geomancerを8体倒し、Tower of AzoraにいるHamish Bergwortのところへ戻ってください。", "ええい、忌々しい！ この繊細な秘術の計器を調整しようとするたびに、エネルギーの奔流でまた狂わされてしまう。\nその奔流は北から来ているようだ。あの原始的なKoboldsが粗雑な魔法の練習をしている所だ。私が研究を続けられるよう、奴らを何匹か片付けてくれないか？", nil, nil, 0x7065a8eb, 0xe5f80ea7, 0x91c5f081, nil, nil, "...mm" },
  [91724] = { "繊細な計器", "Stone Cairn LakeでDefias Rogue Wizardを6体倒し、Tower of AzoraにいるHamish Bergwortのところへ戻ってください。", "あと少しで……なんと、Netherにかけて！ まだ何かが計器を乱している。\n実に苛立たしいよ、{name}。地元の山賊どもがStone Cairn Lakeの近くで呪文の練習をしているという噂を聞いた。奴らを止めれば、この乱れもようやく収まって、研究が進むかもしれないな？", nil, nil, 0x7065a8eb, 0xb6e0db48, 0xe7761ff1, nil, nil, "...mm" },
  [91725] = { "Stolen Enchanting Supplies", "Stone Cairn Lake周辺のgnollのキャンプからStolen Enchanting Suppliesを5個集め、Tower of Azoraの近くにいるBlixie Fitzwinkのところへ戻ってください。", "Master Theocritusに言われて交易所までenchanting suppliesを受け取りに行ったんですが、帰り道でgnollの群れに襲われてしまったんです！\n\n荷物を落として逃げてきましたが、持たずに帰ったら、罰として何週間もpolymorphの実験の後片付けをさせられてしまいます！ 代わりに見つけてきてもらえませんか？", nil, nil, 0x78bd98c1, 0xeda8b676, 0xd9d3fe8f, nil, nil, "...mm" },
  [91732] = { "良質な鋼", "Jasperlode MineからMining Toolsを4個集め、Eastvale Logging CampにいるHagar Loweのところへ戻ってください。", "戦争のあと良質な鋼は不足していて、我々の道具もそのせいで傷んでいる。Jasperlodeの鉱夫たちは精巧に作られたツルハシを使っていた。その一部はまだ鉱山の奥に残っているだろう。いくつか取ってきてくれないか。その鋼を再利用できるか試してみよう。", nil, nil, 0x72aed2a2, 0xd649abdf, 0x8701f873, nil, nil, "...mm" },
  [91733] = { "下流へ", "Eastvale Logging Campから下流へ流されたWaterlogged Axe、Waterlogged Saw、Waterlogged Toolboxを集め、Ormin Pelfordのところへ戻ってください。", "交易所から補給品を運んで帰る途中、荷馬車がひっくり返って、補給品が川に落ちてしまったんだ！ 捕まえる前に、もう下流へ流されてしまった。\nあそこにはmurlocや狼がいるから、僕一人じゃ取り戻せる見込みはない。君はたくましそうだね。見つけてきてくれないか？", nil, nil, 0x5377b6c2, 0x4104ac2d, 0xf5998821, nil, nil, "...mm" },
  [91736] = { "Applejackの蒸留器", nil, nil, nil, nil, 0xdf027785, nil, nil, nil, nil, ".mmmm" },
  [91738] = { "リンゴのごちそう", nil, nil, nil, nil, 0xc00668c0, nil, nil, nil, nil, ".mmmm" },
  [91740] = { "Croaky's Head", "Croaky's HeadをRidgepoint TowerにいるMerell Rossに届けてください。", "このmurlocは間違いなく、しばらくの間このあたりの道を脅かしていたのだろう。近くの見張りの衛兵たちはその死を知りたがるに違いない。", nil, nil, 0x9a2d8e95, 0xfefeb249, 0x70acafd1, nil, nil, "...mm" },
  [91741] = { "Nibbled-On Book", "本をBrother Paxtonに返してください。", "<koboldの一匹がこの本を落とした。koboldが食べようとしたようだ。\n\n修道院の中のBrother Paxtonが小さな図書室を管理している。本はそこから来たに違いない。>", nil, nil, 0xdc36fd8f, 0x60fd6d4c, 0x926272a4, nil, nil, "...mm" },
  [91743] = { "いたずらなネズミども", "Northshire ValleyのkoboldからStolen Bookを$N1冊取り戻し、Brother Paxtonに返してください。", "あのひどいkoboldどもが私の本を食べているんです！ 私の図書室を丸ごと平らげてしまう前に、取り戻してください。", nil, nil, 0x5ecfe128, 0xca0dec56, 0x36c2ff3a, nil, nil, "...mm" },
  [91745] = { "Miningの相談役", "Northshire ValleyのEcho Ridge Mineの外にいるKelsey Fargoと話してください。", "新しい採掘見習いのKelsey Fargoと話してきてくれ。彼女は鉱山のすぐ外で働いていて、koboldどもが何をしているか見ているはずだ。ついでに採掘について少し教えてもらえるかもしれないな。", nil, nil, 0x70de9b61, 0x928069a0, 0x595703ec, nil, nil, "...mm" },
  [91746] = { "Elmpaw's Head", "Elmpaw's HeadをGoldshireの近くにいるHelene Peltskinnerに届けてください。", "この戦利品は、Elmpawに対するあなたの勝利を見事に思い出させてくれる。地元のハンターや皮はぎ職人なら、その話を聞きたがるかもしれない。", nil, nil, 0x6c96dddb, 0xa7c38435, 0x2ae37dbd, nil, nil, "...mm" },
  [91751] = { "Rough Wolf Pelts", "Elwynn Forest周辺の狼の皮をはいでRough Wolf Peltを7枚手に入れ、Goldshireの近くにいるHelene Peltskinnerに届けてください。", "Skinningの練習の機会を探しているの？ 夫はいつも狼狩りを手伝ってくれるんだけど、今は修道院のほうで忙しくて。受けている注文を仕上げるのに、毛皮をもっと集める手伝いがほしいのよ。", nil, nil, 0xe1344efa, 0x7a609a25, 0x993378eb, nil, nil, "...mm" },
  [91752] = { "全体像", "Shinyfinder NarfからSack of \"Picture\" Booksを取り戻してください。その袋をNorthshire's Abbeyのすぐ中にいるMarshal McBrideのところへ持って行ってください。", "時々、koboldが「Narfに絵を！」って叫びながら通っていくんだ。Narfが誰かは知らない。鉱山の奥にいるkoboldの親玉の一匹かな？ きっと今頃は本を袋いっぱい持ってるよ。\n\nその本を取ってきて、ここの保安官、Marshal McBrideに届けて。友達を連れていったほうがいい。鉱山の中のkoboldはずっと凶暴だから。", nil, nil, 0xf0a9a4ae, 0x0274d4d1, 0x64d74190, nil, nil, "...mm" },
  [91753] = { "Enchantingの手ほどき", "Tower of AzoraにいるKitta Firewindは、Luminous Residueを3個集めてほしいと言っています。\n\nLuminous Residueは、Kobold Geomancerが落とすCrude Wax Effigiesを分解すると手に入ります。", "学問的な厳密さはもちろん付呪師の技に欠かせないが、実践的な基礎も大いに役立つものだ。例として、卑しいKoboldを考えてみたまえ。正式な教育を受けていないにもかかわらず、奴らは簡単な呪文や付呪に生来の素質のようなものを示す。\n\n奴らの蝋人形をいくつか手に入れ、その中に込められた付呪を分解してみたまえ。得るところがあるかもしれん。", nil, nil, 0x775e64ad, 0x5706d360, 0x77774694, nil, nil, "...mm" },
  [91758] = { "あのKoboldを追え！", "Northshire's Abbeyの裏の厩舎の近くにいるTordrin Sternbladeと話してください。", "koboldの件はまだ終わっていないぞ。Kelseyから、koboldが本の詰まった大きな袋を持って鉱山を出ていったと知らせがあった。Brother Paxtonのために本を取り戻せるよう、そのkoboldを追跡してほしい。\n\nTordrin Sternbladeと話してくれ。Ironforgeから来たばかりの新しいハンターのトレーナーだ。修道院の裏、厩舎の近くにいる。このkoboldの泥棒を追跡する手助けをしてくれるだろう。", nil, nil, 0x5b4c7f86, 0xba85d0f1, 0xbabf3db2, nil, nil, "...mm" },
  [91772] = { "しーっ！ Koboldsを狩ってるんだ", "koboldの足跡をたどり、わかったことを報告してKobold Tracking Kitを渡しに、GoldshireにいるMarshal Dughanのところへ行ってください。", "よし。このkobold tracking kitを持っていけ。Marshal McBrideが気にしているkoboldを追跡できるはずだ。\n\n足跡をたどって、見つけたものをGoldshireのMarshal Dughanに届けてくれ。\n\nこの害獣どもはNorthshireの外で何か企んでいる気がする。だからDughanの助けが要るだろう。", nil, nil, 0xccca4f37, 0x4c6f788d, 0x88b384bf, nil, nil, "...mm" },
  [91775] = { "本の返却", "Lost Bookを6冊と\"Fun with Elementals\"を見つけ、Marshal Dughanに返してください。", "Fargodeep Mineを調べるついでに、Brother Paxtonの本が見つかったら返してやってくれ。特にPaxtonは「Fun with Elementals」という題の本をとても心配している。koboldでもそれを使って精霊の召使いを呼び出せると考えているんだ。気をつけろ、鉱山の奥はかなり危険だ。仲間を連れていったほうがいい。\n\n見つけた本を守るため、この本袋を持っていけ！", nil, nil, 0xd01af3bc, 0x88f1a8d6, 0xf4a33e50, nil, nil, "...mm" },
  [91777] = { "希少本", "\"Geomancy for Curious Young Wizards\"と\"Arcane Explainer: Magical Stuff in Simple Words\"を取り戻し、Northshire's Abbeyの中にいるBrother Paxtonに返してください。", "Brother Paxtonのリストで行方不明の本はあと2冊だけだ。「Geomancy for Curious Young Wizards」と「Arcane Explainer: Magical Stuff in Simple Words」だ。\n\nkoboldどもがJasperlode Mineに持っていったに違いない。その2冊を探し出して、Brother Paxtonに届けてくれ。\n\nだが、かなり危険だろう。「見習い」のkoboldが精霊を召喚していたのなら、親玉が何をできるか分かったものじゃない。私なら仲間を連れていくな。", nil, nil, 0xa9c579cb, 0xa02ab9c4, 0xae7537c1, nil, nil, "...mm" },
  [91858] = { "外交問題", "Silverpine ForestのThe Sepulcherへ行き、行方不明のEarthen Ringの旅人たちについてTrevan Rolと話してください。", "Silverpineでの実に不運な出来事が、hordeの目に我々の価値を示す絶好の機会をもたらした。\n\nEarthen Ringの使節二人が、Tarren Millへ向かう途中Silverpine Forestで行方不明になった。それ以上のことはほとんど分かっていないが、噂ではかなりの外交問題になりつつあるらしい。行方不明者を取り戻せれば、我々が切実に必要としている正当性を得る助けになるだろう。\n\nThe Sepulcherに我々の者、Trevan Rolがいる。そこへ行って彼と話してくれ。", nil, nil, 0x860aa6df, 0x49857281, 0x51cda335, nil, nil, "...mm" },
  [91859] = { "奇妙な二人組", "最近The Sepulcherを通っていった謎のEarthen Ringの旅人たちについて、Deathguard Baldrenと話してください。", "単刀直入に言おう、この「使節」はただの外交官じゃない。一人はトーレンだった。Earthen Ringならよくあることだが、もう一人は――信じられないだろうが――elfだった。*high* elfだ。二人ともマントで身を隠していたが、俺はquel'doreiを見たことがあるし、大事な小指を賭けてもいい、あれはそうだった。\n\nなぜelfがトーレンに同行してhordeの領土を通っていたのか？ さあな、俺にも分からん。俺が知っているのはそこまでだ。町の入口近くにいるDeathguard Baldrenと話すといい。", nil, nil, 0x81390067, 0x9840d880, 0x5b66726d, nil, nil, "...mm" },
  [91860] = { "過酷な運命", "東にあるFenris Isleを調べ、Earthen Ringの旅の一行がどうなったのか突き止めてください。", "昨夜の巡回中、gnollの一団がFenris Isleの岸辺で、とても大きな死体を薪の山に投げ込んでいるのを見た。elfやもっと小さな死体は見なかったが、彼らにとって良い兆しではないだろうな。\n\n勇敢か愚かなら、Fenris Isleに突っ込んで詳しく調べてもいいが、俺に言わせれば、とっくに死んでいそうな高慢なelfを探すのは骨折り損だ。\n\nパラディンってのは誓いを立てたり負け戦を引き受けたりするのが好きなのは知ってるが、これはその価値がない。信じろ。", nil, nil, 0x08dbafc9, 0x269e6b75, 0x87c0f0e8, nil, nil, "...mm" },
  [91861] = { "Fenris Keepへ", "北にあるFenris Keepを調べ、Earthen Ringの一行の行方不明者を探してください。", "<見つかった死体が一つだけだったのは希望の持てる兆しだ。TrevanとHadrecが言っていたHigh Elfは、近くの砦のもっと奥でまだ生きているのではないか？>", nil, nil, 0x52a5ca6c, 0x05375492, 0x87c8daeb, nil, nil, "...mm" },
  [91862] = { "Lumina Windsinger", "Rot Hide GnollからFenris Isle Keyを取り戻し、それを使ってLumina Windsingerを解放してください。", "Quel'dorei？ いいえ、私は「quel'dorei」ではありません。私はLumina Windsinger、shen'doreiです。Windshaper Skyborneの一人です。\n\n私はEarthen Ringの客人としてこの地に来ました。仲間のBanonと私は、Arathi Highlandsへ向かうためにSilverpineを通っていました。そこで精霊の合流点を調べるためです。見ての通り、たどり着けませんでしたが。\n\nでも今はそんな話をしている時間はありません。近くのgnollを倒してください。この檻の鍵を取り戻して、私を解放してください。安全な所まで逃げたら、残りをお話しします。", nil, nil, 0x8615ca23, 0x9d3e70b4, 0x1c33efa2, nil, nil, "...mm" },
  [91899] = { "Sealed Crate", nil, nil, nil, nil, 0xfc2b137e, nil, nil, nil, nil, ".mmmm" },
  [91900] = { "Sealed Crate", nil, nil, nil, nil, 0xfc2b137e, nil, nil, nil, nil, ".mmmm" },
  [91904] = { "Sealed Crate", nil, nil, nil, nil, 0xfc2b137e, nil, nil, nil, nil, ".mmmm" },
  [91920] = { "野生の目", "murlocの目を3個集め、SepulcherにいるApothecary Renferrelのところへ持って行ってください。", "Apothecary Renferrelの調合の効果を疑うつもりはないが、あの薬に目立った違いがあったと言えば嘘になる。\n\nLake Lordamereの岸辺にはmurlocがうじゃうじゃいる。そして注目すべきことに、murlocには目がある。薬剤師殿の新しいことへの意欲は、最近の心臓への執着で抑え込まれているのだろう。彼にいくつか持っていってやってくれ。\n\nいずれ二度目の死を迎えるか、やり方を疑ったせいでRenferrelに殺されるかを選ぶなら、私は後者を選ぶ。", nil, nil, 0x44275ed7, 0xd4c23f40, 0x9795c646, nil, nil, "...mm" },
  [91921] = { "Quinnのもとへ（再び）", "Quinnの薬を、Sepulcherの北のIvar PatchにいるQuinn Yorickのところへ持って行ってください。", "これがQuinnの回復を助ける新しい薬だ。心臓丸ごと6つから抽出した愛情で作ってある。\n\nさて、君がいるとまた書類仕事が増えるので、失礼させてもらうよ。", nil, nil, 0x641834db, 0xed042c3f, 0x0c746cd7, nil, nil, "...mm" },
})
